<?php require __DIR__.'/includes/layout.php';$id=(int)($_GET['id']??0);$row=null;try{$q=db()->prepare('SELECT * FROM csOrders WHERE ID=?');$q->execute([$id]);$row=$q->fetch();}catch(Throwable){}admin_header('Заказ #'.$id);?><div class="card"><?php if(!$row): ?><p>Заказ не найден.</p><?php else: ?><div class="table-wrap"><table class="table"><tbody><?php foreach($row as $k=>$v): ?><tr><th><?=aesc((string)$k)?></th><td><?=nl2br(aesc(a_legacy((string)$v)))?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><div class="actions" style="margin-top:16px"><a class="btn" href="orders.php">← К списку</a></div></div><?php admin_footer();
